<?php	/**	 * Created by PhpStorm.	 * User: me664	 * Date: 1/15/15	 * Time: 12:07 AM	 */	echo '<div class="content-learn">';	$learn_cat = get_terms( 'learn_cat', array( 'hide_empty' => FALSE ) );	if ( ! is_wp_error( $learn_cat ) ):		?>		<div class="text-center learn_nav " role="tabpanel">			<ul class="nav nav-tabs" role="tablist">				<?php					foreach ( $learn_cat as $k => $cat ):						if ( $k == 0 ) {							$class = 'class="active"';						} else {							$class = '';						}						echo '<li role="presentation" ' . $class . '><a href="#' . $cat->term_id . '" aria-controls="'.$cat->term_id.'" role="tab" data-toggle="tab">' . $cat->name . '</a></li>';						?>					<?php endforeach;?>			</ul>		</div>		<div class="tab-content">			<?php foreach ( $learn_cat as $key => $cat ):; ?>				<?php				$argv  = array(					'post_type'      => 'learn',					'posts_per_page' => - 1,					'tax_query'      => array(						array(							'taxonomy' => 'learn_cat',							'terms'    => $cat->term_id,						),					),				);				$query = new WP_Query( $argv );				if ( $query->have_posts() ) {					if($key==0){						$class="active";					}else{						$class='';					}					echo '<div role="tabpanel" class="tab-pane '.$class.'" id="'.$cat->term_id.'">';					while ( $query->have_posts() ) {						$query->the_post();						echo Hatt()->load_template( 'loop/learn', 'archive' );					}					echo '</div>';					wp_reset_postdata();				} else {					_e( "No Result", HATT_TEXTDOMAIN );				}; ?>			<?php endforeach;?>		</div>	<?php endif; ?>